import sys; sys.path.insert(0, '/home/claude')
from corr_gen import C, write_all

C(20, [
 ("Compte, root verrouillé, identité et budget", "# console : MFA sur root, puis plus jamais root ; IAM Identity Center : utilisateur gael, groupe Admins, permission set AdministratorAccess sur le compte sandbox\n# budget : Billing → Budgets → 20 $/mois, alertes 50/80/100 % par mail ; Cost Explorer activé\nalias awsc='docker run --rm -it -v \"$HOME/.aws:/root/.aws\" amazon/aws-cli'\nawsc configure sso   # session, start URL, région eu-west-3, profil sandbox\nawsc sso login --profile sandbox && awsc sts get-caller-identity --profile sandbox", "{ \"UserId\": \"AROA…:gael\", \"Account\": \"123456789012\", \"Arn\": \"arn:aws:sts::123456789012:assumed-role/AWSReservedSSO_AdministratorAccess_…/gael\" }", ["Aucune clé d'accès statique n'existe : la connexion SSO produit des identifiants de courte durée dans <code>~/.aws</code>, monté dans le conteneur.", "Le budget est créé avant la première ressource : c'est la règle du chapitre, et ce qui te réveille avant la facture."]),
 ("Garde-fous : régions, CloudTrail, GuardDuty, Config", "awsc cloudtrail create-trail --name org-trail --s3-bucket-name crisis-trail-123456789012 --is-multi-region-trail --profile sandbox && awsc cloudtrail start-logging --name org-trail --profile sandbox\nawsc guardduty create-detector --enable --profile sandbox\nawsc configservice put-configuration-recorder --configuration-recorder name=default,roleARN=arn:aws:iam::123456789012:role/aws-service-role/config.amazonaws.com/AWSServiceRoleForConfig --recording-group allSupported=true --profile sandbox\n# SCP (si Organizations) : refuser toute région hors eu-west-3 et eu-west-1", "trail actif multi-région, détecteur GuardDuty actif, Config en enregistrement", ["CloudTrail répond à « qui a fait quoi » ; GuardDuty à « quelque chose d'anormal ? » ; Config à « quelque chose de non conforme ? ». Les trois avant toute charge de travail.", "Le bucket du trail est en écriture seule pour CloudTrail et en lecture pour l'audit : personne d'autre."]),
 ("Un premier service, et son coût observé", "awsc s3 mb s3://crisis-sandbox-123456789012-artefacts --profile sandbox\nawsc s3api put-public-access-block --bucket crisis-sandbox-123456789012-artefacts --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true --profile sandbox\nawsc s3api put-bucket-encryption --bucket … --server-side-encryption-configuration '{\"Rules\":[{\"ApplyServerSideEncryptionByDefault\":{\"SSEAlgorithm\":\"aws:kms\"}}]}' --profile sandbox\nawsc ce get-cost-and-usage --time-period Start=2026-09-01,End=2026-09-22 --granularity MONTHLY --metrics UnblendedCost --profile sandbox --query 'ResultsByTime[0].Total.UnblendedCost.Amount'", "\"0.31\"", ["Bloquer l'accès public et chiffrer par défaut sont les deux réglages de tout bucket, avant d'y mettre quoi que ce soit.", "Cost Explorer en ligne de commande : c'est la source du rapport FinOps du TP 23."]),
 ("Tout détruire, et vérifier", "awsc s3 rb s3://crisis-sandbox-123456789012-artefacts --force --profile sandbox\nawsc resourcegroupstaggingapi get-resources --profile sandbox --query 'ResourceTagMappingList[].ResourceARN'", "[]   (ne restent que le trail, GuardDuty, Config, qui coûtent quelques centimes)", ["Le réflexe de fin de séance : lister ce qui reste et détruire ce qui n'est pas la fondation. Une instance oubliée, c'est 30 $ à la fin du mois.", "Tag <code>Owner</code> et <code>Env</code> sur tout dès maintenant : le TP 23 en a besoin."]),
], ["Un compte avec root sous MFA et inutilisé, Identity Center configuré, profil SSO fonctionnel en conteneur, budget et alertes, CloudTrail multi-région, GuardDuty, Config.", "<code>tp20.md</code> : la sortie de <code>get-caller-identity</code> (rôle SSO, pas d'utilisateur IAM), les captures budget et alertes, la vérification « rien ne reste » en fin de TP.", "Aucune clé d'accès dans <code>~/.aws/credentials</code> (le fichier n'existe pas)."],
 ["Pourquoi Identity Center plutôt qu'un utilisateur IAM avec MFA ? Rotation automatique, sessions courtes, une identité pour tous les comptes, révocation centrale.", "Que fait une SCP que l'IAM d'un compte ne peut pas faire ? Elle s'impose même à l'administrateur du compte."])

C(21, [
 ("Réseau : VPC trois niveaux sur trois zones, en module", "module \"network\" {\n  source = \"terraform-aws-modules/vpc/aws\"\n  version = \"~> 5.13\"\n  name = \"crisis-prod\" ; cidr = \"10.20.0.0/16\" ; azs = [\"eu-west-3a\", \"eu-west-3b\", \"eu-west-3c\"]\n  public_subnets = [\"10.20.1.0/24\", \"10.20.2.0/24\", \"10.20.3.0/24\"]\n  private_subnets = [\"10.20.11.0/24\", \"10.20.12.0/24\", \"10.20.13.0/24\"]\n  database_subnets = [\"10.20.21.0/24\", \"10.20.22.0/24\", \"10.20.23.0/24\"]\n  enable_nat_gateway = true ; single_nat_gateway = true   # un seul NAT : coût ; en prod critique, one_nat_gateway_per_az\n  enable_dns_hostnames = true\n}\nresource \"aws_vpc_endpoint\" \"s3\" { vpc_id = module.network.vpc_id, service_name = \"com.amazonaws.eu-west-3.s3\", route_table_ids = module.network.private_route_table_ids }\nresource \"aws_vpc_endpoint\" \"ecr_dkr\" { vpc_id = module.network.vpc_id, service_name = \"com.amazonaws.eu-west-3.ecr.dkr\", vpc_endpoint_type = \"Interface\", subnet_ids = module.network.private_subnets, security_group_ids = [aws_security_group.endpoints.id], private_dns_enabled = true }", "Plan: 38 to add (VPC, 9 subnets, IGW, NAT, tables, endpoints)", ["Le module communautaire évite 300 lignes ; on lit ses entrées, on ne le réécrit pas.", "Les endpoints S3 et ECR évitent de payer le NAT pour tirer les images et écrire les logs : c'est le levier FinOps numéro un du TP 23."]),
 ("Sécurité : security groups par référence, secrets, rôles", "resource \"aws_security_group\" \"alb\" { vpc_id = module.network.vpc_id ; ingress { from_port = 443, to_port = 443, protocol = \"tcp\", cidr_blocks = [\"0.0.0.0/0\"] } ; egress { from_port = 0, to_port = 0, protocol = \"-1\", cidr_blocks = [\"0.0.0.0/0\"] } }\nresource \"aws_security_group\" \"api\" { vpc_id = module.network.vpc_id ; ingress { from_port = 8080, to_port = 8080, protocol = \"tcp\", security_groups = [aws_security_group.alb.id] } ; egress { from_port = 0, to_port = 0, protocol = \"-1\", cidr_blocks = [\"0.0.0.0/0\"] } }\nresource \"aws_security_group\" \"db\" { vpc_id = module.network.vpc_id ; ingress { from_port = 5432, to_port = 5432, protocol = \"tcp\", security_groups = [aws_security_group.api.id] } }\nresource \"aws_secretsmanager_secret\" \"db\" { name = \"crisis/prod/db\" }\nresource \"random_password\" \"db\" { length = 32, special = false }\nresource \"aws_secretsmanager_secret_version\" \"db\" { secret_id = aws_secretsmanager_secret.db.id, secret_string = jsonencode({ username = \"crisis\", password = random_password.db.result }) }\nresource \"aws_iam_role\" \"task\" { name = \"crisis-api-task\", assume_role_policy = data.aws_iam_policy_document.ecs_assume.json }\nresource \"aws_iam_role_policy\" \"task\" { role = aws_iam_role.task.id, policy = jsonencode({ Version = \"2012-10-17\", Statement = [{ Effect = \"Allow\", Action = [\"secretsmanager:GetSecretValue\"], Resource = aws_secretsmanager_secret.db.arn }] }) }", "chaîne : Internet → SG alb (443) → SG api (8080, depuis alb) → SG db (5432, depuis api)", ["Aucun CIDR interne dans les règles : uniquement des références de security group. Ajouter une tâche ne change aucune règle.", "Le mot de passe est généré par Terraform et stocké dans Secrets Manager ; il est dans le state (chiffré, accès restreint) : la version avec <code>ephemeral</code> et rotation gérée est le pas suivant."]),
 ("Base RDS multi-AZ et calcul", "resource \"aws_db_instance\" \"main\" {\n  identifier = \"crisis-prod\" ; engine = \"postgres\" ; engine_version = \"16.4\" ; instance_class = \"db.t4g.medium\" ; allocated_storage = 50 ; storage_type = \"gp3\" ; storage_encrypted = true\n  db_subnet_group_name = module.network.database_subnet_group ; vpc_security_group_ids = [aws_security_group.db.id] ; publicly_accessible = false ; multi_az = true\n  username = \"crisis\" ; password = random_password.db.result ; db_name = \"crisis\"\n  backup_retention_period = 7 ; deletion_protection = true ; skip_final_snapshot = false ; final_snapshot_identifier = \"crisis-prod-final\"\n  performance_insights_enabled = true ; lifecycle { prevent_destroy = true }\n}\nresource \"aws_ecs_cluster\" \"main\" { name = \"crisis\" }\nresource \"aws_ecs_task_definition\" \"api\" { family = \"api\", requires_compatibilities = [\"FARGATE\"], network_mode = \"awsvpc\", cpu = 512, memory = 1024, execution_role_arn = aws_iam_role.exec.arn, task_role_arn = aws_iam_role.task.arn,\n  container_definitions = jsonencode([{ name = \"api\", image = \"${aws_ecr_repository.api.repository_url}@${var.api_digest}\", portMappings = [{ containerPort = 8080 }],\n    secrets = [{ name = \"SPRING_DATASOURCE_PASSWORD\", valueFrom = \"${aws_secretsmanager_secret.db.arn}:password::\" }],\n    environment = [{ name = \"SPRING_DATASOURCE_URL\", value = \"jdbc:postgresql://${aws_db_instance.main.address}:5432/crisis\" }],\n    logConfiguration = { logDriver = \"awslogs\", options = { \"awslogs-group\" = \"/crisis/api\", \"awslogs-region\" = \"eu-west-3\", \"awslogs-stream-prefix\" = \"api\" } },\n    healthCheck = { command = [\"CMD-SHELL\", \"wget -qO- http://localhost:8080/actuator/health || exit 1\"], interval = 15, startPeriod = 60 } }]) }\nresource \"aws_ecs_service\" \"api\" { name = \"api\", cluster = aws_ecs_cluster.main.id, task_definition = aws_ecs_task_definition.api.arn, desired_count = 2, launch_type = \"FARGATE\",\n  network_configuration { subnets = module.network.private_subnets, security_groups = [aws_security_group.api.id] }\n  load_balancer { target_group_arn = aws_lb_target_group.api.arn, container_name = \"api\", container_port = 8080 }\n  deployment_circuit_breaker { enable = true, rollback = true } ; lifecycle { ignore_changes = [desired_count] } }", "ECS : 2 tâches RUNNING en subnets privés ; RDS multi-AZ, non public, chiffré, suppression protégée", ["Fargate évite de gérer des instances : pas de patch, pas de SSH ; l'image est référencée par digest.", "<code>deployment_circuit_breaker</code> avec rollback : un déploiement dont les tâches ne deviennent pas saines revient seul en arrière.", "<code>ignore_changes = [desired_count]</code> : c'est l'autoscaling qui pilote ce nombre, pas Terraform."]),
 ("Équilibreur, certificat, DNS, WAF", "resource \"aws_lb\" \"main\" { name = \"crisis\", load_balancer_type = \"application\", subnets = module.network.public_subnets, security_groups = [aws_security_group.alb.id], drop_invalid_header_fields = true }\nresource \"aws_acm_certificate\" \"api\" { domain_name = \"api.crisisshield.example\", validation_method = \"DNS\" }\nresource \"aws_lb_listener\" \"https\" { load_balancer_arn = aws_lb.main.arn, port = 443, protocol = \"HTTPS\", ssl_policy = \"ELBSecurityPolicy-TLS13-1-2-2021-06\", certificate_arn = aws_acm_certificate.api.arn, default_action { type = \"forward\", target_group_arn = aws_lb_target_group.api.arn } }\nresource \"aws_lb_listener\" \"http\" { load_balancer_arn = aws_lb.main.arn, port = 80, protocol = \"HTTP\", default_action { type = \"redirect\", redirect { port = \"443\", protocol = \"HTTPS\", status_code = \"HTTP_301\" } } }\nresource \"aws_route53_record\" \"api\" { zone_id = var.zone_id, name = \"api.crisisshield.example\", type = \"A\", alias { name = aws_lb.main.dns_name, zone_id = aws_lb.main.zone_id, evaluate_target_health = true } }\nresource \"aws_wafv2_web_acl_association\" \"alb\" { resource_arn = aws_lb.main.arn, web_acl_arn = aws_wafv2_web_acl.main.arn }   # règles gérées AWS : CommonRuleSet, KnownBadInputs, limite de débit\ncurl -sI https://api.crisisshield.example/actuator/health | head -1 ; curl -sI http://api.crisisshield.example | head -1", "HTTP/2 200\nHTTP/1.1 301 Moved Permanently", ["TLS 1.2 minimum et redirection HTTP → HTTPS ; le certificat ACM se renouvelle seul tant que l'enregistrement de validation DNS existe.", "Le WAF avec les règles gérées coûte quelques dollars et arrête le bruit (scanners, injections triviales) avant l'application."]),
 ("Ce que ça coûte, et la destruction", "docker run --rm -v \"$PWD:/w\" -w /w -e INFRACOST_API_KEY infracost/infracost breakdown --path envs/prod | tail -8\n# fin de TP : terraform destroy (retirer prevent_destroy et deletion_protection avant), puis vérification par tagging API", "OVERALL TOTAL  $161.40/mois  (NAT 32 $, RDS multi-AZ 68 $, Fargate 2 tâches 30 $, ALB 22 $, …)", ["Le chiffre justifie chaque choix : multi-AZ double la base, le NAT unique économise 64 $, les endpoints évitent la facture de trafic.", "La destruction est un test : ce qui résiste (<code>prevent_destroy</code>) est ce qu'on a déclaré comme précieux."]),
], ["Le dépôt Terraform <code>envs/prod</code> avec module VPC, endpoints, security groups par référence, Secrets Manager, rôles de tâche, RDS multi-AZ protégée, ECS Fargate par digest avec circuit breaker, ALB TLS 1.2+, redirection, Route 53, WAF.", "<code>tp21.md</code> : le schéma de la chaîne (DNS → ALB → tâches → RDS), les deux curl, le coût infracost commenté, la preuve de destruction complète.", "Le cours joint : ce qui a été fait, pourquoi Fargate, pourquoi le digest, comment expliquer les security groups par référence en entretien."],
 ["Pourquoi <code>single_nat_gateway</code> en sandbox et un NAT par zone en production critique ? Une panne de zone couperait la sortie Internet des deux autres.", "Comment fait-on tourner le mot de passe RDS sans redémarrer les tâches ? Rotation Secrets Manager avec fonction, et l'application relit le secret à la reconnexion."])

C(22, [
 ("Le même service décrit trois fois, sans compte", "# Azure : main.azure.tf (azurerm) — resource_group, virtual_network, subnet, container_app_environment + container_app (ou app_service), postgresql_flexible_server, key_vault\n# GCP : main.gcp.tf (google) — compute_network, subnetwork, cloud_run_v2_service, sql_database_instance (POSTGRES_16), secret_manager_secret, cloud_run_v2_service_iam_member\nalias tf='docker run --rm -v \"$PWD:/w\" -w /w hashicorp/terraform:1.9'\nfor c in aws azure gcp; do (cd $c && tf init -backend=false >/dev/null && tf validate && echo \"$c : valide\"); done", "aws : valide\nazure : valide\ngcp : valide", ["<code>validate</code> sans compte vérifie la syntaxe et le schéma des providers : c'est la revue de code des trois versions.", "Le tableau d'équivalences du chapitre 22 est la grille : ALB ↔ Application Gateway ↔ Cloud Load Balancing, RDS ↔ Flexible Server ↔ Cloud SQL, Secrets Manager ↔ Key Vault ↔ Secret Manager, rôle de tâche ↔ identité managée ↔ compte de service."]),
 ("Ce qui est identique, ce qui diffère", "diff <(grep -o 'resource \"[a-z_]*\"' aws/*.tf | sort -u) <(grep -o 'resource \"[a-z_]*\"' azure/*.tf | sort -u) | head\n# tableau tp22.md : réseau, calcul, base, secrets, identité, journaux, coût estimé (calculateurs publics), verrouillage", "les concepts sont identiques (réseau privé, calcul managé, base managée, secret, identité de charge) ; les noms, les valeurs par défaut et l'identité diffèrent", ["Le portable : le conteneur, Terraform, OpenTelemetry, PostgreSQL. Le spécifique : identité (IAM / Entra ID / IAM Google), réseau, facturation, services serverless.", "Identité managée Azure et Workload Identity GCP jouent le rôle du rôle de tâche AWS : aucune clé dans les trois cas."]),
 ("Estimation de coût et décision", "# calculateurs : AWS Pricing Calculator, Azure Pricing Calculator, Google Cloud Pricing Calculator ; même profil : 2 conteneurs 0,5 vCPU / 1 Go, base 2 vCPU multi-zone 50 Go, 100 Go de sortie\n# tp22.md : tableau des trois totaux, écart, et la recommandation : un cloud principal (celui de l'entreprise ou des compétences), briques portables, pas de multi-cloud actif", "AWS ≈ 160 $, Azure ≈ 175 $, GCP ≈ 150 $ (ordres de grandeur ; l'écart est inférieur au coût d'une équipe multi-cloud)", ["Le vrai coût du multi-cloud est humain : trois vocabulaires, trois identités, trois facturations. On en conclut un cloud principal et une architecture portable, pas trois déploiements.", "Cette conclusion est la réponse d'entretien attendue à « multi-cloud ou pas ? »."]),
], ["Trois répertoires Terraform (<code>aws</code>, <code>azure</code>, <code>gcp</code>) qui passent <code>validate</code>, le tableau d'équivalences rempli, les trois estimations de coût.", "<code>tp22.md</code> : portable contre spécifique en deux colonnes, et la recommandation argumentée.", "Aucun compte créé : tout est validé hors ligne."],
 ["Que faut-il pour qu'une application passe d'AWS à GCP en une semaine ? Conteneur, PostgreSQL, secrets lus par variable, identité par rôle, zéro appel de SDK propriétaire dans le code.", "Quand un multi-cloud actif se justifie-t-il ? Exigence réglementaire ou client explicite, jamais par principe."])

C(23, [
 ("Tags obligatoires et allocation", "# variables communes : default_tags dans le provider\nprovider \"aws\" { region = \"eu-west-3\" ; default_tags { tags = { Owner = \"gael\", Env = var.env, Service = \"crisisshield\", CostCenter = \"lab\" } } }\n# règle Config ou politique OPA : toute ressource sans Owner et Env est non conforme\nawsc ce get-cost-and-usage --time-period Start=2026-09-01,End=2026-09-22 --granularity MONTHLY --metrics UnblendedCost --group-by Type=TAG,Key=Env --profile sandbox --query 'ResultsByTime[0].Groups[].[Keys[0],Metrics.UnblendedCost.Amount]' --output table", "Env$prod   118.20\nEnv$dev     41.90\n(sans tag)   3.10", ["<code>default_tags</code> garantit que tout ce que Terraform crée est attribuable ; ce qui apparaît « sans tag » a été créé à la main.", "L'allocation par tag est l'étape « informer » : sans elle, personne n'est responsable d'aucun coût."]),
 ("Les leviers, dans l'ordre : éteindre, redimensionner, architecture", "# 1. éteindre : dev la nuit et le week-end — EventBridge Scheduler + aws ecs update-service --desired-count 0 à 20 h, 2 à 7 h ; RDS dev : aws rds stop-db-instance\n# 2. redimensionner : Compute Optimizer / Performance Insights : db.t4g.medium à 12 % CPU → db.t4g.small ; tâches Fargate 512/1024 → 256/512 si p95 tient (k6, TP 13)\n# 3. architecture : endpoints S3 et ECR (déjà), logs CloudWatch avec rétention 30 j, S3 Intelligent-Tiering sur les artefacts, Graviton (t4g) partout\n# 4. engagements : Savings Plan Compute 1 an sur le socle stable seulement (prod), après un mois de mesure\nawsc ce get-cost-forecast --time-period Start=2026-10-01,End=2026-11-01 --metric UNBLENDED_COST --granularity MONTHLY --profile sandbox --query 'Total.Amount'", "avant : 163 $/mois → après leviers 1 à 3 : 96 $/mois (−41 %) ; engagement ensuite : −12 % supplémentaires", ["Éteindre ne demande aucune décision d'architecture et rapporte le plus : c'est toujours le premier levier.", "On ne s'engage (Savings Plan) qu'après avoir optimisé : s'engager sur du gaspillage le fige pour un an."]),
 ("Coût par unité et rapport mensuel", "# métrique : coût mensuel / nombre d'incidents traités (ou de requêtes) → coût par incident\n# tableau de bord : Cost Explorer (coût par service, par tag), CloudWatch (requêtes), une ligne « coût par 1 000 requêtes »\n# rapport tp23.md : coût par équipe, top 3 des services, leviers appliqués avec gain mesuré, prévision, décisions à prendre", "coût par 1 000 requêtes : 0,42 $ → 0,25 $ ; la croissance du trafic (+30 %) ne fait plus monter la facture", ["Le coût par unité est la seule métrique qui distingue croissance et gaspillage : une facture qui monte avec le trafic est saine si le coût unitaire baisse.", "Le rapport mensuel avec des décisions est l'étape « opérer » : le FinOps est une routine, pas un projet."]),
 ("Alerte d'anomalie et garde-fous", "awsc ce create-anomaly-monitor --anomaly-monitor '{\"MonitorName\":\"services\",\"MonitorType\":\"DIMENSIONAL\",\"MonitorDimension\":\"SERVICE\"}' --profile sandbox\nawsc ce create-anomaly-subscription --anomaly-subscription '{\"SubscriptionName\":\"mail\",\"MonitorArnList\":[\"arn:…\"],\"Subscribers\":[{\"Type\":\"EMAIL\",\"Address\":\"gael@…\"}],\"Threshold\":10,\"Frequency\":\"DAILY\"}' --profile sandbox\n# budget par environnement (dev 40 $, prod 130 $), action automatique : au-delà de 100 % en dev, la politique IAM de création est retirée", "détecteur d'anomalies actif ; budgets avec alertes et action", ["L'anomalie détectée en un jour vaut mieux qu'une facture découverte le 1er du mois.", "Une action de budget en dev (couper les créations) est acceptable ; en prod, on alerte, on ne coupe pas."]),
], ["<code>default_tags</code> dans Terraform, la règle de conformité des tags, le calendrier d'extinction du dev, les redimensionnements justifiés par des mesures, les endpoints et rétentions, le détecteur d'anomalies et les budgets.", "<code>tp23.md</code> : coût par tag avant/après, les leviers appliqués avec le gain chiffré, le coût par unité, la prévision, trois décisions pour le mois prochain.", "La règle écrite : engagement seulement après un mois d'optimisation mesurée."],
 ["Pourquoi le NAT Gateway est-il le poste caché classique ? Chaque Go vers S3 ou ECR le traverse sans endpoint, à 0,05 $ le Go plus l'heure.", "Que fait-on d'un coût « sans tag » ? On le retrouve par CloudTrail (qui a créé la ressource), on tague ou on supprime, on empêche par politique."])

C(24, [
 ("Hybride en local : deux « sites » reliés par un tunnel", "docker network create site-a ; docker network create site-b\ndocker run -d --name wg-a --cap-add NET_ADMIN --network site-a -e PEERS=1 linuxserver/wireguard   # ou Tailscale : docker run -d --name ts-a --network site-a -e TS_AUTHKEY=… tailscale/tailscale\ndocker run -d --name wg-b --cap-add NET_ADMIN --network site-b linuxserver/wireguard\n# échanger les clés publiques, configurer AllowedIPs, puis :\ndocker exec wg-a ping -c 2 10.13.13.2 ; docker exec wg-a wg show | grep -E 'transfer|latest handshake'", "2 packets transmitted, 2 received\nlatest handshake: 3 seconds ago ; transfer: 1.2 KiB received, 1.5 KiB sent", ["Deux réseaux Docker isolés qui se parlent uniquement par le tunnel : c'est le Direct Connect ou le VPN site-à-site, en miniature.", "Tailscale simplifie tout (identité, NAT traversal) : c'est ce que le homelab (7.5) utilise ; WireGuard pur montre ce qu'il y a dessous."]),
 ("Identité fédérée et GitOps unique", "# Keycloak sur site-a joue l'annuaire d'entreprise ; l'IdP « cloud » (un second Keycloak sur site-b) est configuré en identity brokering vers le premier (OIDC)\n# ArgoCD sur site-b synchronise le même dépôt Git que l'agent du TP 19 sur site-a : envs/onprem et envs/cloud, même apps/\ncurl -s http://keycloak-b:8080/realms/cloud/.well-known/openid-configuration | jq -r .issuer\n# se connecter à ArgoCD (site-b) avec un compte du Keycloak de site-a", "https://keycloak-b/realms/cloud   (connexion réussie avec un compte du site A : fédération)", ["Une identité, deux plateformes : l'utilisateur ne sait pas où tourne le service.", "Un seul dépôt de configuration avec deux dossiers d'environnement : la même façon de déployer des deux côtés, la propriété hybride qui compte."]),
 ("Observabilité centralisée et plan de réversibilité", "# Prometheus site-a en remote_write vers un Mimir/Prometheus site-b (ou l'inverse) via le tunnel ; un seul Grafana\n# docs/reversibilite.md : pour chaque brique cloud utilisée, l'équivalent on-prem, le format d'export des données, le temps estimé de retour, ce qui est verrouillant (services serverless, IAM) et la décision associée\ncurl -s http://prom-b:9090/api/v1/query?query=up | jq '.data.result | length'", "12   (les cibles des deux sites dans un seul Prometheus)", ["La réversibilité se planifie avant d'entrer : format des données, identité, réseau, ce qu'on accepte de perdre.", "C'est un document attendu des DSI publiques (SecNumCloud, souveraineté) : sache le produire."]),
], ["Deux réseaux Docker reliés par WireGuard ou Tailscale, fédération OIDC entre deux Keycloak, un dépôt GitOps avec deux environnements, une observabilité centralisée à travers le tunnel.", "<code>tp24.md</code> : preuve du tunnel (handshake), preuve de la fédération (connexion croisée), la requête <code>up</code> des deux sites, et le plan de réversibilité en une page.", "Un paragraphe : ce qui reste identique des deux côtés (identité, déploiement, observabilité) et ce qui diffère (réseau, coût, services)."],
 ["Pourquoi fédérer l'IdP cloud vers l'annuaire du site plutôt que l'inverse ? L'annuaire de l'entreprise est la source de vérité des comptes ; le cloud en consomme.", "Quel est le premier signe qu'un hybride est mal fait ? Deux façons de déployer, deux tableaux de bord, deux astreintes."])

C(25, [
 ("Cluster kind à trois nœuds, kubectl en conteneur", "cat > kind-config.yaml <<'EOF'\nkind: Cluster\napiVersion: kind.x-k8s.io/v1alpha4\nnodes:\n  - role: control-plane\n    kubeadmConfigPatches: [\"kind: InitConfiguration\\nnodeRegistration:\\n  kubeletExtraArgs:\\n    node-labels: \\\"ingress-ready=true\\\"\"]\n    extraPortMappings: [{ containerPort: 80, hostPort: 80 }, { containerPort: 443, hostPort: 443 }]\n  - role: worker\n  - role: worker\nEOF\ndocker run --rm -v /var/run/docker.sock:/var/run/docker.sock -v \"$PWD:/w\" -w /w --network host kindest/node:v1.31.0 sh -c 'true' 2>/dev/null ; true\n# kind lui-même en conteneur (image outillée avec kind, kubectl, helm, k9s, stern, krew) :\ndocker build -t devops-tools -f tools/Dockerfile tools/ && alias k='docker run --rm -it -v /var/run/docker.sock:/var/run/docker.sock -v \"$HOME/.kube:/root/.kube\" -v \"$PWD:/w\" -w /w --network host devops-tools'\nk kind create cluster --name crisis --config kind-config.yaml && k kubectl get nodes -o wide", "NAME                   STATUS   ROLES           VERSION\ncrisis-control-plane   Ready    control-plane   v1.31.0\ncrisis-worker          Ready    <none>          v1.31.0\ncrisis-worker2         Ready    <none>          v1.31.0", ["Trois nœuds pour voir le scheduler répartir, drainer un nœud, observer une éviction.", "L'image outillée (<code>tools/Dockerfile</code>) contient kind, kubectl, helm, k9s, stern, krew et ses plugins : rien sur le poste, même kubectl."]),
 ("Composants du control plane, vus de près", "k kubectl get pods -n kube-system -o wide\nk kubectl get --raw='/readyz?verbose' | tail -5\ndocker exec crisis-control-plane crictl ps --name kube-apiserver -q\ndocker exec crisis-control-plane sh -c 'ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key get /registry/namespaces/default --keys-only'", "etcd, kube-apiserver, kube-controller-manager, kube-scheduler (static pods), coredns ×2, kindnet ×3, kube-proxy ×3\nreadyz check passed\n/registry/namespaces/default   (l'objet est bien dans etcd)", ["Les quatre composants du control plane sont des Pods statiques lancés par le kubelet à partir de <code>/etc/kubernetes/manifests</code> : voir <code>ls</code> dans le conteneur du control plane.", "Lire directement dans etcd rend concret le chapitre : kubectl ne fait que parler à l'API qui écrit là."]),
 ("Kata de débogage : huit scénarios cassés", "mkdir -p k8s/kata && for i in 1 2 3 4 5 6 7 8; do :; done\n# casse-1 : Service avec selector app=apii (typo) → get endpointslices vide → describe svc\n# casse-2 : targetPort 8081 → curl depuis netshoot vers le Pod passe, vers le Service échoue\n# casse-3 : image crisisshield/api:1.9.99 → ImagePullBackOff → describe pod : manifest unknown\n# casse-4 : livenessProbe sur /actuator/health avec dépendance base coupée → CrashLoopBackOff → logs --previous\n# casse-5 : ResourceQuota 1 CPU sur le namespace, Deployment à 3 réplicas de 500m → 1 Pending → describe rs : exceeded quota\n# casse-6 : NetworkPolicy default-deny sans règle egress DNS → nslookup échoue → describe netpol, ajouter egress 53\n# casse-7 : PVC storageClassName: fast (inexistante) → Pending → get sc\n# casse-8 : PDB minAvailable: 3 avec 3 réplicas → kubectl drain bloque → describe pdb\nk kubectl apply -f k8s/kata/casse-1.yaml ; k kubectl get endpointslices -l kubernetes.io/service-name=api", "NAME   ADDRESSTYPE   PORTS   ENDPOINTS\napi-x  IPv4          8080    <unset>       (vide : le sélecteur ne matche personne)", ["Pour chaque casse : trois commandes maximum jusqu'au diagnostic, écrites dans <code>k8s/kata/README.md</code> avec la correction. C'est ton entraînement CKA.", "L'ordre du chapitre 25.5 : get, describe (événements), logs --previous, puis Ingress → Service → EndpointSlices → Pod → nœud."]),
 ("Administration : snapshot etcd, certificats, mise à jour", "docker exec crisis-control-plane sh -c 'ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key snapshot save /tmp/etcd.db' && docker cp crisis-control-plane:/tmp/etcd.db .\nk kubectl create ns temoin ; # restaurer le snapshot (kind : recréer le cluster avec le snapshot, ou suivre la procédure kubeadm dans un nœud) → le namespace temoin a disparu\ndocker exec crisis-control-plane kubeadm certs check-expiration | head -5\nk kind create cluster --name crisis-132 --image kindest/node:v1.32.0 --config kind-config.yaml   # mise à jour = nouveau cluster, après Pluto sur les manifests\ndocker run --rm -v \"$PWD:/w\" ghcr.io/fairwindsops/pluto detect-files -d /w/k8s", "Snapshot saved at /tmp/etcd.db\napiserver … Sep 21, 2027   (1 an)\nPluto : No deprecated or removed APIs found", ["Une restauration etcd ramène le cluster à l'état du snapshot : le namespace témoin disparaît. Sur un cluster managé, c'est le fournisseur ; les volumes, eux, relèvent de Velero (chapitre 44).", "Sur kind, la mise à jour se fait par remplacement de cluster : exactement la stratégie « nœuds remplacés » des clusters managés."]),
 ("kubectl expert et outils", "k kubectl get pods -A -o custom-columns='NS:.metadata.namespace,NOM:.metadata.name,NOEUD:.spec.nodeName,RESTARTS:.status.containerStatuses[*].restartCount' | sort -k4 -rn | head -5\nk kubectl auth can-i --list --as=system:serviceaccount:crisis:api | head -5\nk kubectl krew install neat ctx ns tree view-secret 2>&1 | tail -1 ; k kubectl get deploy api -o yaml | k kubectl neat | head -5\nk stern -n crisis api --since 1m ; k k9s", "… (les plugins fonctionnent depuis l'image outillée)", ["Les cinq plugins krew et k9s sont dans l'image outillée : un nouveau poste n'installe rien.", "<code>auth can-i --list --as=…</code> est la question de sécurité numéro un : que peut faire ce ServiceAccount ?"]),
], ["<code>kind-config.yaml</code> à trois nœuds, l'image outillée <code>tools/Dockerfile</code>, les huit manifests de kata avec leur README (diagnostic en trois commandes, correction), le snapshot etcd et la preuve de restauration, la vérification des certificats, le cluster 1.32 après Pluto.", "<code>tp25.md</code> : la sortie de <code>get pods -n kube-system</code> annotée (rôle de chaque composant), la clé lue dans etcd, le tableau des huit casses.", "Aucun binaire Kubernetes sur le poste : tout passe par le conteneur outillé."],
 ["Pourquoi les composants du control plane sont-ils des Pods statiques et non des Deployments ? Il faut qu'ils tournent avant que l'API n'existe.", "Que se passe-t-il si l'API server tombe mais pas les kubelets ? Les Pods continuent de servir ; plus aucun changement n'est possible."])

C(26, [
 ("Namespace, config, secret externe, Deployment de référence", "k kubectl create ns crisis\ncat > k8s/base/deployment.yaml <<'EOF'\napiVersion: apps/v1\nkind: Deployment\nmetadata: { name: api, namespace: crisis, labels: { app: api } }\nspec:\n  replicas: 3\n  revisionHistoryLimit: 5\n  strategy: { type: RollingUpdate, rollingUpdate: { maxSurge: 1, maxUnavailable: 0 } }\n  selector: { matchLabels: { app: api } }\n  template:\n    metadata: { labels: { app: api, version: \"1.7.0\" } }\n    spec:\n      serviceAccountName: api\n      automountServiceAccountToken: false\n      securityContext: { runAsNonRoot: true, runAsUser: 10001, seccompProfile: { type: RuntimeDefault } }\n      topologySpreadConstraints: [{ maxSkew: 1, topologyKey: kubernetes.io/hostname, whenUnsatisfiable: ScheduleAnyway, labelSelector: { matchLabels: { app: api } } }]\n      containers:\n        - name: api\n          image: localhost:5000/crisisshield/api@sha256:a77e…\n          ports: [{ containerPort: 8080, name: http }]\n          envFrom: [{ configMapRef: { name: api-config } }]\n          env: [{ name: SPRING_DATASOURCE_PASSWORD, valueFrom: { secretKeyRef: { name: api-db, key: password } } }]\n          resources: { requests: { cpu: 250m, memory: 512Mi }, limits: { memory: 512Mi } }\n          startupProbe: { httpGet: { path: /actuator/health/liveness, port: http }, failureThreshold: 30, periodSeconds: 2 }\n          livenessProbe: { httpGet: { path: /actuator/health/liveness, port: http }, periodSeconds: 10 }\n          readinessProbe: { httpGet: { path: /actuator/health/readiness, port: http }, periodSeconds: 5 }\n          lifecycle: { preStop: { exec: { command: [sh, -c, \"sleep 5\"] } } }\n          securityContext: { allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: { drop: [ALL] } }\n          volumeMounts: [{ name: tmp, mountPath: /tmp }]\n      volumes: [{ name: tmp, emptyDir: { sizeLimit: 256Mi } }]\n      terminationGracePeriodSeconds: 30\nEOF\nk kubectl apply -f k8s/base/ && k kubectl rollout status deploy/api -n crisis && k kubectl get pods -n crisis -o wide", "deployment \"api\" successfully rolled out\napi-7d9f-…  1/1 Running  crisis-worker\napi-7d9f-…  1/1 Running  crisis-worker2\napi-7d9f-…  1/1 Running  crisis-control-plane (ou worker : spread)", ["Chaque ligne du Deployment de référence a une raison, listée au chapitre 26.2 ; celui-ci est copié tel quel par tous les services suivants.", "Limite mémoire = request, pas de limite CPU : Guaranteed sur la mémoire, pas de throttling CPU."]),
 ("Service, Ingress, TLS, et la chaîne vérifiée", "k kubectl apply -f https://raw.githubusercontent.com/kubernetes/ingress-nginx/main/deploy/static/provider/kind/deploy.yaml\ncat > k8s/base/service-ingress.yaml <<'EOF'\napiVersion: v1\nkind: Service\nmetadata: { name: api, namespace: crisis }\nspec: { selector: { app: api }, ports: [{ port: 80, targetPort: http }] }\n---\napiVersion: networking.k8s.io/v1\nkind: Ingress\nmetadata: { name: api, namespace: crisis, annotations: { cert-manager.io/cluster-issuer: selfsigned } }\nspec:\n  ingressClassName: nginx\n  tls: [{ hosts: [api.crisis.local], secretName: api-tls }]\n  rules: [{ host: api.crisis.local, http: { paths: [{ path: /, pathType: Prefix, backend: { service: { name: api, port: { number: 80 } } } }] } }]\nEOF\nk kubectl apply -f k8s/base/service-ingress.yaml\nk kubectl get endpointslices -n crisis -l kubernetes.io/service-name=api\ncurl -sk --resolve api.crisis.local:443:127.0.0.1 https://api.crisis.local/actuator/health", "api-xxxxx  IPv4  8080  10.244.1.7,10.244.2.9,10.244.3.4\n{\"status\":\"UP\"}", ["EndpointSlice avec trois adresses = le sélecteur matche et les Pods sont prêts ; c'est la première chose à regarder quand un Service ne répond pas.", "<code>--resolve</code> évite de toucher au fichier hosts du poste."]),
 ("RBAC, NetworkPolicy, quotas, isolation", "cat > k8s/base/security.yaml <<'EOF'\napiVersion: v1\nkind: ServiceAccount\nmetadata: { name: api, namespace: crisis }\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: Role\nmetadata: { name: dev-readonly, namespace: crisis }\nrules: [{ apiGroups: [\"\", \"apps\"], resources: [pods, pods/log, deployments, services], verbs: [get, list, watch] }]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: RoleBinding\nmetadata: { name: devs, namespace: crisis }\nsubjects: [{ kind: Group, name: crisis-devs, apiGroup: rbac.authorization.k8s.io }]\nroleRef: { kind: Role, name: dev-readonly, apiGroup: rbac.authorization.k8s.io }\n---\napiVersion: networking.k8s.io/v1\nkind: NetworkPolicy\nmetadata: { name: default-deny, namespace: crisis }\nspec: { podSelector: {}, policyTypes: [Ingress, Egress] }\n---\napiVersion: networking.k8s.io/v1\nkind: NetworkPolicy\nmetadata: { name: api-allow, namespace: crisis }\nspec:\n  podSelector: { matchLabels: { app: api } }\n  ingress: [{ from: [{ namespaceSelector: { matchLabels: { kubernetes.io/metadata.name: ingress-nginx } } }], ports: [{ port: 8080 }] }]\n  egress:\n    - { to: [{ podSelector: { matchLabels: { app: db } } }], ports: [{ port: 5432 }] }\n    - { to: [{ namespaceSelector: { matchLabels: { kubernetes.io/metadata.name: kube-system } } }], ports: [{ port: 53, protocol: UDP }, { port: 53, protocol: TCP }] }\n---\napiVersion: v1\nkind: ResourceQuota\nmetadata: { name: crisis, namespace: crisis }\nspec: { hard: { requests.cpu: \"4\", requests.memory: 8Gi, pods: \"20\" } }\nEOF\nk kubectl apply -f k8s/base/security.yaml\nk kubectl auth can-i delete pods -n crisis --as=alice --as-group=crisis-devs ; k kubectl auth can-i get pods -n crisis --as=alice --as-group=crisis-devs\nk kubectl label ns crisis pod-security.kubernetes.io/enforce=restricted", "no\nyes\nnamespace/crisis labeled   (aucun avertissement : le Deployment respecte restricted)", ["kind utilise kindnet, qui n'applique pas les NetworkPolicies : pour les voir agir, installer Calico ou Cilium (<code>disableDefaultCNI: true</code> dans la config kind). Note-le dans <code>tp26.md</code> ; le test du DNS coupé fait partie du kata 6 du TP 25.", "PSA restricted sur le namespace : tout Pod non conforme est refusé ; le Deployment de référence passe."]),
 ("Manifests avancés, QoS, canary manuel", "# init container Flyway, sidecar natif (initContainers avec restartPolicy: Always), Downward API POD_NAME, jeton projeté audience vault, ndots 2, enableServiceLinks false\nk kubectl get pods -n crisis -o custom-columns='NOM:.metadata.name,QOS:.status.qosClass'\n# canary : Deployment api-canary, 1 réplica, même label app=api, image 1.8.0\nfor i in $(seq 40); do curl -sk --resolve api.crisis.local:443:127.0.0.1 https://api.crisis.local/api/version; done | sort | uniq -c", "api-…  Burstable  (×3)   — aucun BestEffort\n     30 1.7.0\n     10 1.8.0   (le Service répartit sur les 4 Pods : 25 % de canary)", ["Un canary à deux Deployments derrière un Service est proportionnel au nombre de Pods : pour 10 %, il faut 9 contre 1. Argo Rollouts (chapitre 31) pondère sans ce contrainte.", "La classe QoS se lit dans le statut : c'est l'ordre d'éviction en cas de pression mémoire."]),
 ("Les vingt questions, à voix haute", "# section 26.8 : 20 questions, 45 s chacune, chronométrées et enregistrées ; noter celles où tu hésites dans tp26.md", "", ["C'est le seul entraînement qui prépare l'entretien Kubernetes : réponse courte, structure, exemple.", "Refais l'exercice une semaine plus tard : les hésitations doivent avoir changé."]),
], ["<code>k8s/base/</code> : Deployment de référence, Service, Ingress TLS, ServiceAccount, Role et RoleBinding, NetworkPolicies default-deny et api-allow, ResourceQuota, namespace en PSA restricted, init container, sidecar natif, canary manuel.", "<code>tp26.md</code> : l'EndpointSlice à trois adresses, le curl à travers l'Ingress, les deux <code>auth can-i</code>, les classes QoS, le comptage du canary, et la note sur le CNI de kind.", "Le cours joint : les cinq objets et comment expliquer le Deployment de référence ligne par ligne."],
 ["Pourquoi <code>maxUnavailable: 0</code> avec <code>maxSurge: 1</code> ? Jamais moins de trois Pods prêts pendant un rolling update : zéro perte de capacité.", "Que se passe-t-il si la readiness échoue sur un seul Pod ? Il sort de l'EndpointSlice ; le Service continue avec les deux autres."])

C(27, [
 ("StorageClass, PVC, et la preuve de persistance", "k kubectl get storageclass\ncat > k8s/storage/pvc-test.yaml <<'EOF'\napiVersion: v1\nkind: PersistentVolumeClaim\nmetadata: { name: test, namespace: crisis }\nspec: { accessModes: [ReadWriteOnce], resources: { requests: { storage: 1Gi } } }\n---\napiVersion: v1\nkind: Pod\nmetadata: { name: writer, namespace: crisis }\nspec: { containers: [{ name: w, image: alpine, command: [sh, -c, \"echo persistant > /data/f && sleep 3600\"], volumeMounts: [{ name: d, mountPath: /data }] }], volumes: [{ name: d, persistentVolumeClaim: { claimName: test } }] }\nEOF\nk kubectl apply -f k8s/storage/pvc-test.yaml && sleep 5 && k kubectl delete pod writer -n crisis && k kubectl run reader -n crisis --image=alpine --overrides='{\"spec\":{\"containers\":[{\"name\":\"r\",\"image\":\"alpine\",\"command\":[\"cat\",\"/data/f\"],\"volumeMounts\":[{\"name\":\"d\",\"mountPath\":\"/data\"}]}],\"volumes\":[{\"name\":\"d\",\"persistentVolumeClaim\":{\"claimName\":\"test\"}}]}}' --restart=Never && sleep 3 && k kubectl logs reader -n crisis", "standard (default)  rancher.io/local-path  WaitForFirstConsumer\npersistant   (le fichier a survécu à la suppression du Pod)", ["Le PVC est lié quand le premier Pod est planifié (<code>WaitForFirstConsumer</code>) : le disque est créé sur le bon nœud.", "Local-path sur kind : un PV lié à un nœud ; si le nœud disparaît, le disque aussi. C'est la raison de l'opérateur ci-dessous."]),
 ("PostgreSQL en haute disponibilité avec CloudNativePG", "k kubectl apply --server-side -f https://raw.githubusercontent.com/cloudnative-pg/cloudnative-pg/release-1.24/releases/cnpg-1.24.0.yaml\ncat > k8s/storage/cluster.yaml <<'EOF'\napiVersion: postgresql.cnpg.io/v1\nkind: Cluster\nmetadata: { name: crisis-db, namespace: crisis }\nspec:\n  instances: 3\n  imageName: ghcr.io/cloudnative-pg/postgresql:16.4\n  storage: { size: 5Gi }\n  bootstrap: { initdb: { database: crisis, owner: crisis } }\n  postgresql: { parameters: { max_connections: \"200\", shared_buffers: 256MB } }\n  monitoring: { enablePodMonitor: true }\n  backup:\n    barmanObjectStore: { destinationPath: s3://crisis-backups/, endpointURL: http://minio.minio:9000, s3Credentials: { accessKeyId: { name: minio, key: ACCESS_KEY_ID }, secretAccessKey: { name: minio, key: ACCESS_SECRET_KEY } } }\n    retentionPolicy: 7d\nEOF\nk kubectl apply -f k8s/storage/cluster.yaml && sleep 90 && k kubectl get cluster -n crisis && k kubectl get pods -n crisis -l cnpg.io/cluster=crisis-db", "crisis-db   3 instances   Cluster in healthy state   primary: crisis-db-1\ncrisis-db-1  Running (primary)  crisis-db-2  Running (replica)  crisis-db-3  Running (replica)", ["L'opérateur encode le savoir-faire DBA : réplication, bascule, sauvegardes, PITR, monitoring. Un StatefulSet nu n'aurait aucune bascule automatique.", "Les Services <code>crisis-db-rw</code> (primaire) et <code>crisis-db-ro</code> (réplicas) sont créés : l'application écrit sur rw, lit sur ro."]),
 ("Bascule provoquée, et ce que voit l'application", "k kubectl delete pod crisis-db-1 -n crisis & \\\nfor i in $(seq 30); do k kubectl exec -n crisis deploy/api -- wget -qO- localhost:8080/actuator/health/readiness | cut -c1-30 ; sleep 1; done | sort | uniq -c\nk kubectl get cluster -n crisis -o jsonpath='{.status.currentPrimary}'", "     27 {\"status\":\"UP\"}\n      3 {\"status\":\"DOWN\"}   (≈ 3 s de bascule)\ncrisis-db-2   (nouveau primaire)", ["Trois secondes d'indisponibilité en écriture : c'est le coût réel d'une bascule, à comparer aux minutes d'une intervention manuelle.", "Le pool de connexions de l'application (Hikari) retente : c'est lui qui rend la bascule invisible aux utilisateurs."]),
 ("Sauvegarde, restauration dans le temps, et snapshot", "k kubectl apply -f - <<'EOF'\napiVersion: postgresql.cnpg.io/v1\nkind: Backup\nmetadata: { name: crisis-db-manual, namespace: crisis }\nspec: { cluster: { name: crisis-db } }\nEOF\nk kubectl get backup -n crisis\n# restauration PITR dans un nouveau cluster :\n# spec.bootstrap.recovery: { source: crisis-db, recoveryTarget: { targetTime: \"2026-09-22 10:40:00+00\" } } + externalClusters vers le même object store\nk kubectl get cluster crisis-db-restored -n crisis -o jsonpath='{.status.phase}'", "crisis-db-manual   completed   (dans MinIO : base/ et wals/)\nCluster in healthy state   (les données d'avant 10 h 40 sont là)", ["La restauration est testée dans un cluster séparé, jamais par-dessus la production : c'est aussi comme ça qu'on teste chaque semaine.", "PITR = sauvegarde de base + journaux WAL : on revient à la seconde près, ce qu'un dump ne permet pas."]),
 ("Longhorn : le stockage réparti, en option", "# kind avec 3 nœuds : installer Longhorn (helm), StorageClass longhorn avec 2 réplicas ; recréer le PVC test en longhorn ; kubectl drain crisis-worker → le Pod redémarre ailleurs avec ses données\nk kubectl get pods -n longhorn-system | grep -c Running", "≥ 12   (le volume répliqué survit à la perte d'un nœud)", ["Longhorn ou Ceph répliquent entre nœuds ; local-path ne le fait pas. En cloud, le CSI du fournisseur (EBS) et les snapshots remplacent ce rôle.", "Pour une base, l'opérateur réplique déjà au niveau applicatif : Longhorn est surtout pour les autres volumes (uploads, files)."]),
], ["Les manifests <code>k8s/storage/</code> : PVC de test, Cluster CloudNativePG à trois instances avec sauvegarde objet (MinIO), Backup manuel, cluster de restauration PITR, éventuellement Longhorn.", "<code>tp27.md</code> : la preuve de persistance, la bascule chronométrée avec les 3 s de DOWN, la sauvegarde complétée, la restauration vérifiée, le drain avec Longhorn.", "L'application modifiée pour écrire sur <code>crisis-db-rw</code> et lire sur <code>crisis-db-ro</code>."],
 ["Pourquoi trois instances et pas deux ? Pour élire un primaire sans ambiguïté et garder une réplique pendant une maintenance.", "Quand utiliser une base managée (RDS) plutôt qu'un opérateur ? Quand l'équipe ne veut pas exploiter PostgreSQL ; l'opérateur quand le cloud n'est pas là ou le coût compte."])

C(28, [
 ("Chart Helm de CrisisShield", "k helm create charts/crisisshield && rm -rf charts/crisisshield/templates/tests charts/crisisshield/templates/hpa.yaml\n# templates/deployment.yaml : le Deployment de référence du TP 26, paramétré (image.digest, replicaCount, resources, probes) ; annotation checksum/config: {{ include (print $.Template.BasePath \"/configmap.yaml\") . | sha256sum }}\n# values.yaml : image: { repository: localhost:5000/crisisshield/api, digest: \"\" } ; values.schema.json avec required: [image] et pattern sur le digest\n# templates/_helpers.tpl : labels standard app.kubernetes.io/*\nk helm lint charts/crisisshield && k helm template api charts/crisisshield -f values-dev.yaml | k kubectl apply --dry-run=server -f -\nk helm unittest charts/crisisshield", "==> Linting charts/crisisshield … 1 chart(s) linted, 0 chart(s) failed\ndeployment.apps/api created (server dry run)\nPASS  crisisshield  tests/deployment_test.yaml  (3 tests)", ["Le checksum du ConfigMap dans l'annotation force le rolling quand la configuration change : sans lui, un changement de ConfigMap ne redémarre rien.", "<code>values.schema.json</code> refuse une installation sans digest : la politique « pas de tag » est dans le chart."]),
 ("Installer, mettre à jour avec diff, revenir", "k helm upgrade --install api charts/crisisshield -n crisis -f values-dev.yaml --set image.digest=sha256:a77e… --atomic --timeout 3m\nk helm diff upgrade api charts/crisisshield -n crisis -f values-dev.yaml --set image.digest=sha256:b12f…\nk helm upgrade --install api charts/crisisshield -n crisis -f values-dev.yaml --set image.digest=sha256:b12f… --atomic\nk helm history api -n crisis ; k helm rollback api 1 -n crisis && k kubectl get deploy api -n crisis -o jsonpath='{.spec.template.spec.containers[0].image}'", "REVISION 1 deployed … REVISION 2 deployed\nRollback was a success\nlocalhost:5000/crisisshield/api@sha256:a77e…", ["<code>--atomic</code> revient seul si les Pods ne deviennent pas prêts : un déploiement Helm n'est jamais laissé cassé.", "Le diff avant l'upgrade est la revue : il montre exactement les lignes qui changent."]),
 ("Overlays Kustomize pour dev et prod", "mkdir -p kustomize/{base,overlays/dev,overlays/prod}\n# base : les manifests bruts du TP 26 + kustomization.yaml (resources, commonLabels)\ncat > kustomize/overlays/prod/kustomization.yaml <<'EOF'\napiVersion: kustomize.config.k8s.io/v1beta1\nkind: Kustomization\nresources: [../../base]\nnamespace: crisis-prod\nreplicas: [{ name: api, count: 5 }]\nimages: [{ name: localhost:5000/crisisshield/api, digest: sha256:b12f… }]\npatches:\n  - target: { kind: Deployment, name: api }\n    patch: |\n      - op: replace\n        path: /spec/template/spec/containers/0/resources/requests/memory\n        value: 1Gi\nconfigMapGenerator: [{ name: api-config, literals: [SPRING_PROFILES_ACTIVE=prod, LOG_LEVEL=INFO] }]\nEOF\nk kubectl kustomize kustomize/overlays/prod | k kubectl apply --dry-run=server -f - && k kubectl kustomize kustomize/overlays/prod | grep -E 'replicas|image:|name: api-config'", "replicas: 5\nimage: localhost:5000/crisisshield/api@sha256:b12f…\nname: api-config-8f7c6d2k4h   (hash : tout changement redéploie)", ["Kustomize ne fait que superposer : pas de logique, pas de conditions, donc pas d'erreur de template ; c'est son avantage pour ses propres applications.", "Le suffixe de hash du ConfigMap joue le rôle du checksum Helm."]),
 ("Charts tiers : lire les valeurs, épingler, scanner", "k helm repo add bitnami https://charts.bitnami.com/bitnami && k helm repo update\nk helm show values bitnami/redis --version 20.1.0 | grep -nE 'auth:|enabled:|architecture' | head\nk helm template redis bitnami/redis --version 20.1.0 --set architecture=standalone --set auth.password=x | docker run --rm -i aquasec/trivy config -   # ou kyverno apply policies/ --resource -\n# Chart.yaml de crisisshield : dependencies: [{ name: redis, version: 20.1.0, repository: https://charts.bitnami.com/bitnami, condition: redis.enabled }]", "auth.enabled: true (défaut sûr) ; architecture: replication (3 Pods : à vérifier avant d'installer)\ntrivy : 2 MEDIUM (runAsNonRoot manquant sur un sidecar de métriques) → values à ajuster", ["Lire les valeurs par défaut d'un chart tiers avant de l'installer : un LoadBalancer ou une réplication imprévue coûtent cher.", "Les manifests rendus sont scannés comme les nôtres : le chart tiers n'est pas exempté."]),
], ["<code>charts/crisisshield</code> avec Deployment de référence paramétré, checksum de config, <code>values.schema.json</code>, tests unitaires ; <code>kustomize/base</code> et overlays dev et prod ; Redis en dépendance épinglée.", "<code>tp28.md</code> : lint, template en dry-run serveur, diff avant upgrade, historique et rollback, le rendu Kustomize prod, le scan d'un chart tiers.", "Une règle écrite : Helm pour les paquets tiers et la distribution, Kustomize pour les overlays de nos applications."],
 ["Pourquoi <code>--atomic</code> et un <code>--timeout</code> ? Sans timeout, un rollout bloqué attend indéfiniment ; sans atomic, il reste bloqué.", "Que se passe-t-il si deux personnes font <code>helm upgrade</code> en même temps ? Helm verrouille la release ; en GitOps, la question disparaît."])

C(29, [
 ("ArgoCD sur kind, connecté à l'IdP", "k kubectl create ns argocd && k kubectl apply -n argocd -f https://raw.githubusercontent.com/argoproj/argo-cd/v2.12.4/manifests/install.yaml\nk kubectl -n argocd patch cm argocd-cm --type merge -p '{\"data\":{\"url\":\"https://argocd.crisis.local\",\"oidc.config\":\"name: Keycloak\\nissuer: https://keycloak.crisis.local/realms/crisis\\nclientID: argocd\\nclientSecret: $oidc.keycloak.clientSecret\\nrequestedScopes: [openid, profile, email, groups]\"}}'\nk kubectl -n argocd patch cm argocd-rbac-cm --type merge -p '{\"data\":{\"policy.csv\":\"g, crisis-admins, role:admin\\ng, crisis-devs, role:readonly\",\"policy.default\":\"\"}}'\nk kubectl -n argocd get secret argocd-initial-admin-secret -o jsonpath='{.data.password}' | base64 -d", "ArgoCD accessible ; connexion Keycloak ; groupe crisis-admins = admin, crisis-devs = lecture", ["<code>policy.default: \"\"</code> : aucun droit par défaut ; le compte admin local est désactivé après la mise en place de l'OIDC.", "L'IdP est hors du cluster (ou dans un namespace séparé) : dépendance circulaire évitée, comme au chapitre 7.5."]),
 ("Le dépôt de configuration et une Application par environnement", "# dépôt crisisshield-config : apps/api (chart ou kustomize base), envs/dev, envs/staging, envs/prod\ncat > argocd/app-dev.yaml <<'EOF'\napiVersion: argoproj.io/v1alpha1\nkind: Application\nmetadata: { name: api-dev, namespace: argocd, finalizers: [resources-finalizer.argocd.argoproj.io] }\nspec:\n  project: crisisshield\n  source: { repoURL: https://gitlab.local/crisisshield/config.git, targetRevision: main, path: envs/dev }\n  destination: { server: https://kubernetes.default.svc, namespace: crisis-dev }\n  syncPolicy: { automated: { prune: true, selfHeal: true }, syncOptions: [CreateNamespace=true, ServerSideApply=true] }\nEOF\nk kubectl apply -f argocd/app-dev.yaml ; k argocd app get api-dev | grep -E 'Health|Sync'", "Health Status:  Healthy\nSync Status:    Synced to main (a1b2c3d)", ["<code>prune</code> supprime ce qui a disparu de Git, <code>selfHeal</code> corrige ce qu'on a modifié à la main : la dérive n'existe plus.", "Un AppProject par équipe limite les dépôts, namespaces et types d'objets autorisés."]),
 ("Dérive corrigée, rollback par revert, promotion par MR", "k kubectl scale deploy api -n crisis-dev --replicas=1 ; sleep 10 ; k kubectl get deploy api -n crisis-dev -o jsonpath='{.spec.replicas}'\n# rollback : git revert du commit de promotion, push ; ArgoCD resynchronise en < 3 min (ou argocd app sync)\n# promotion : MR qui change images[].digest dans envs/prod/kustomization.yaml, revue, pipeline (kubeconform, kyverno test, trivy config), fusion ; prod : syncPolicy manuelle avec fenêtre\nk argocd app sync api-prod --dry-run", "3   (selfHeal a remis la valeur de Git)\n… (dry-run : ce qui changerait en prod)", ["Le rollback est un commit : traçable, revu, et ArgoCD le déploie comme n'importe quel changement.", "Prod en synchronisation manuelle avec fenêtre (<code>syncWindows</code> du projet) : GitOps n'impose pas l'automatique partout."]),
 ("ApplicationSet et environnements éphémères", "cat > argocd/appset-previews.yaml <<'EOF'\napiVersion: argoproj.io/v1alpha1\nkind: ApplicationSet\nmetadata: { name: previews, namespace: argocd }\nspec:\n  generators: [{ pullRequest: { gitlab: { project: \"42\", api: https://gitlab.local, tokenRef: { secretName: gitlab-token, key: token } }, requeueAfterSeconds: 60 } }]\n  template:\n    metadata: { name: 'api-pr-{{number}}' }\n    spec:\n      project: crisisshield\n      source: { repoURL: https://gitlab.local/crisisshield/config.git, targetRevision: '{{branch}}', path: envs/preview, kustomize: { images: ['localhost:5000/crisisshield/api:{{head_sha}}'] } }\n      destination: { server: https://kubernetes.default.svc, namespace: 'pr-{{number}}' }\n      syncPolicy: { automated: { prune: true, selfHeal: true }, syncOptions: [CreateNamespace=true] }\nEOF\nk kubectl apply -f argocd/appset-previews.yaml", "une Application par merge request ouverte, détruite à la fermeture", ["Un environnement par MR, créé et détruit sans ticket : c'est la capacité de plateforme la plus demandée par les développeurs.", "Ici le tag est le SHA du commit de la MR : acceptable en preview, jamais en prod (digest)."]),
 ("Notifications et Image Updater", "k kubectl -n argocd patch cm argocd-notifications-cm --type merge -p '{\"data\":{\"service.slack\":\"token: $slack-token\",\"trigger.on-sync-failed\":\"- send: [app-sync-failed]\\n  when: app.status.operationState.phase in [Error, Failed]\",\"template.app-sync-failed\":\"message: Sync failed {{.app.metadata.name}}\"}}'\n# Image Updater : annotation sur api-dev : argocd-image-updater.argoproj.io/image-list: api=localhost:5000/crisisshield/api ; update-strategy: digest ; write-back-method: git", "notification Slack sur échec ; dev suit automatiquement le dernier digest publié, par commit dans Git", ["Image Updater écrit le nouveau digest dans Git : même en automatique, tout reste dans l'historique.", "Notifier seulement les échecs : un canal qui reçoit chaque synchronisation réussie n'est plus lu."]),
], ["ArgoCD installé avec OIDC et RBAC par groupe, AppProject, une Application par environnement (dev automatique, prod manuelle avec fenêtre), ApplicationSet de previews, notifications, Image Updater sur dev.", "<code>tp29.md</code> : la dérive corrigée par selfHeal, un rollback par revert, une promotion par MR avec le pipeline du dépôt de configuration, une preview créée par une MR.", "Le schéma du flux : commit → CI → digest → MR de promotion → ArgoCD → cluster."],
 ["Pourquoi un dépôt de configuration séparé du code ? Cycle de vie et droits différents : on peut promouvoir sans toucher au code, et les opérations n'ont pas besoin d'écrire dans le dépôt applicatif.", "Que se passe-t-il si ArgoCD tombe ? Rien pour les applications ; seule la synchronisation s'arrête. C'est un composant de la plateforme avec son propre SLO (chapitre 43)."])

C(30, [
 ("Istio en ambient sur kind, et mTLS partout", "k istioctl install --set profile=ambient --skip-confirmation && k kubectl get pods -n istio-system\nk kubectl label ns crisis istio.io/dataplane-mode=ambient\nk kubectl apply -f - <<'EOF'\napiVersion: security.istio.io/v1\nkind: PeerAuthentication\nmetadata: { name: strict, namespace: crisis }\nspec: { mtls: { mode: STRICT } }\nEOF\nk kubectl exec -n crisis deploy/api -- wget -qO- --timeout=3 http://notification:8080/health ; echo \"code $?\"   # depuis un Pod du mesh : OK\nk kubectl run -n default test --rm -it --image=alpine -- wget -qO- --timeout=3 http://notification.crisis:8080/health ; echo \"code $?\"   # hors mesh : refusé", "istiod, ztunnel (DaemonSet), istio-cni : Running\ncode 0 (dans le mesh)\ncode 1 (hors mesh : connexion refusée, mTLS STRICT)", ["Ambient : aucun sidecar, les Pods de l'application ne changent pas ; ztunnel sur chaque nœud chiffre et authentifie.", "STRICT refuse le trafic en clair : la preuve par le Pod hors mesh."]),
 ("Autorisation par identité de service, pas par IP", "k kubectl apply -f - <<'EOF'\napiVersion: security.istio.io/v1\nkind: AuthorizationPolicy\nmetadata: { name: notification-allow, namespace: crisis }\nspec:\n  selector: { matchLabels: { app: notification } }\n  action: ALLOW\n  rules: [{ from: [{ source: { principals: [\"cluster.local/ns/crisis/sa/api\"] } }], to: [{ operation: { methods: [POST], paths: [\"/notify\"] } }] }]\nEOF\nk kubectl exec -n crisis deploy/api -- wget -qO- --post-data='{}' http://notification:8080/notify ; echo\nk kubectl exec -n crisis deploy/web -- wget -qO- --post-data='{}' http://notification:8080/notify ; echo \"code $?\"", "{\"sent\":true}\ncode 1   (web n'est pas autorisé : RBAC-access-denied)", ["L'identité est le ServiceAccount, transporté par le certificat SPIFFE : une politique par appelant, sans IP.", "C'est la couche « service à service » de l'authentification du chapitre 41.7, sans code applicatif."]),
 ("Canary pondéré et repli avec un waypoint", "k istioctl waypoint apply -n crisis --enroll-namespace\nk kubectl apply -f - <<'EOF'\napiVersion: gateway.networking.k8s.io/v1\nkind: HTTPRoute\nmetadata: { name: api-canary, namespace: crisis }\nspec:\n  parentRefs: [{ group: \"\", kind: Service, name: api }]\n  rules:\n    - backendRefs: [{ name: api-v1, port: 80, weight: 90 }, { name: api-v2, port: 80, weight: 10 }]\n      timeouts: { request: 2s }\n      retries: { attempts: 2, backoff: 100ms }\nEOF\nfor i in $(seq 100); do k kubectl exec -n crisis deploy/web -- wget -qO- http://api/api/version; done | sort | uniq -c", "     90 1.7.0\n     10 1.8.0", ["10 % exactement, indépendamment du nombre de Pods : c'est ce que le canary à deux Deployments (TP 26) ne savait pas faire.", "Timeout et retries sont dans la route, pas dans le code : les patrons de résilience deviennent de la configuration."]),
 ("Observabilité du mesh et coût", "k kubectl apply -f https://raw.githubusercontent.com/istio/istio/release-1.23/samples/addons/kiali.yaml -f …/prometheus.yaml\nk kubectl port-forward -n istio-system svc/kiali 20001:20001 &\n# graphe des services, taux d'erreur et latence par lien, sans instrumentation\nk kubectl top pods -n istio-system", "ztunnel ≈ 30 Mi par nœud, istiod ≈ 100 Mi ; latence ajoutée < 1 ms en ambient", ["Le mesh donne les métriques RED de chaque appel sans toucher au code : c'est son second argument après le mTLS.", "Le coût en ambient est faible ; en sidecar, comptez 50 à 100 Mi par Pod et une latence de quelques ms : c'est la raison du choix ambient."]),
], ["Istio ambient installé, PeerAuthentication STRICT, AuthorizationPolicy par ServiceAccount, waypoint et HTTPRoute pondérée avec timeout et retries, Kiali.", "<code>tp30.md</code> : les deux tests mTLS (dans et hors mesh), les deux tests d'autorisation, le comptage 90/10, la capture Kiali, la mesure de coût.", "Un paragraphe : quand un mesh se justifie (mTLS obligatoire, dizaines de services, canary pondéré) et quand il est superflu."],
 ["Que fait STRICT sur un Pod qui n'est pas dans le mesh mais qui doit appeler un service du mesh ? Refus : il faut l'enrôler ou créer une exception PERMISSIVE ciblée.", "Pourquoi le waypoint est-il nécessaire pour l'HTTPRoute ? ztunnel travaille en L4 ; le routage HTTP (L7) demande un proxy waypoint par namespace."])

C(31, [
 ("Requests justes, HPA, et la charge", "k kubectl apply -f https://github.com/kubernetes-sigs/metrics-server/releases/latest/download/components.yaml && k kubectl patch -n kube-system deploy metrics-server --type=json -p '[{\"op\":\"add\",\"path\":\"/spec/template/spec/containers/0/args/-\",\"value\":\"--kubelet-insecure-tls\"}]'\nk kubectl autoscale deploy api -n crisis --cpu-percent=70 --min=2 --max=8\ndocker run --rm -i --network host -v \"$PWD:/w\" grafana/k6 run /w/load.js --vus 50 --duration 3m &\nk kubectl get hpa api -n crisis -w", "api   Deployment/api   35%/70%   2   8   2\napi   Deployment/api   142%/70%  2   8   4\napi   Deployment/api   68%/70%   2   8   6", ["L'HPA ne fonctionne qu'avec des requests définies : le pourcentage est relatif à la request, pas au nœud.", "Le comportement de montée est rapide et la descente lente (stabilisation de 5 min) : c'est voulu pour éviter les oscillations."]),
 ("Cluster autoscaler simulé, PDB, éviction", "k kubectl scale deploy api -n crisis --replicas=12 ; k kubectl get pods -n crisis | grep -c Pending\n# sur kind, « ajouter un nœud » = kind ne le permet pas à chaud ; documenter : en cloud, Cluster Autoscaler ou Karpenter crée un nœud pour les Pending en ~90 s\nk kubectl apply -f - <<'EOF'\napiVersion: policy/v1\nkind: PodDisruptionBudget\nmetadata: { name: api, namespace: crisis }\nspec: { minAvailable: 2, selector: { matchLabels: { app: api } } }\nEOF\nk kubectl drain crisis-worker --ignore-daemonsets --delete-emptydir-data && k kubectl get pods -n crisis -o wide | grep -v crisis-worker | wc -l ; k kubectl uncordon crisis-worker", "3 Pending (plus de place : c'est le signal pour l'autoscaler de nœuds)\nnode/crisis-worker drained   (les Pods ont migré, jamais moins de 2 disponibles)", ["Le drain respecte le PDB : il attend que les Pods soient recréés ailleurs avant d'évincer les suivants.", "Un PDB trop strict (minAvailable = réplicas) bloque tout drain : c'est le kata 8 du TP 25."]),
 ("KEDA : à zéro, et sur une file", "k helm repo add kedacore https://kedacore.github.io/charts && k helm install keda kedacore/keda -n keda --create-namespace --version 2.15.1\nk kubectl apply -f - <<'EOF'\napiVersion: keda.sh/v1alpha1\nkind: ScaledObject\nmetadata: { name: worker, namespace: crisis }\nspec:\n  scaleTargetRef: { name: worker }\n  minReplicaCount: 0\n  maxReplicaCount: 10\n  triggers: [{ type: kafka, metadata: { bootstrapServers: kafka.crisis:9092, consumerGroup: notifications, topic: incidents, lagThreshold: \"50\" } }]\nEOF\n# produire 500 messages : le worker passe de 0 à 10 ; file vidée : retour à 0 après cooldown", "worker : 0 → 10 réplicas pendant le pic, 0 après", ["Scaler sur le retard de consommation (lag) plutôt que sur le CPU : la file est la vraie mesure de la charge d'un worker.", "Le zéro réplica est le vrai gain de coût : un worker qui ne fait rien ne coûte rien."]),
 ("VPA, requests réelles, et Argo Rollouts", "k kubectl apply -f https://raw.githubusercontent.com/kubernetes/autoscaler/master/vertical-pod-autoscaler/deploy/…   # ou : docker run … ghcr.io/robusta-dev/krr:latest simple\nk kubectl get vpa api -n crisis -o jsonpath='{.status.recommendation.containerRecommendations[0].target}'\n# Argo Rollouts : Rollout avec strategy.canary steps [setWeight 10, pause 2m, analysis (taux d'erreur < 1 % via Prometheus), setWeight 50, pause, 100]\nk kubectl argo rollouts get rollout api -n crisis --watch", "{\"cpu\":\"180m\",\"memory\":\"420Mi\"}   (request CPU 250m trop haute, mémoire juste)\nrollout api : canary 10 % → analysis Successful → 50 % → 100 %", ["Le VPA en mode recommandation (ou KRR) donne les requests réelles : c'est la source pour corriger le Deployment de référence, jamais des chiffres devinés.", "Le Rollout avec analyse automatise le runbook du TP 15 : les seuils de la revue de fiabilité deviennent des critères de promotion."]),
], ["metrics-server, HPA avec charge k6 et sa montée observée, PDB avec drain réussi, KEDA sur Kafka de 0 à 10, VPA ou KRR en recommandation, un Rollout canary avec analyse.", "<code>tp31.md</code> : les captures <code>get hpa -w</code>, le nombre de Pending sans place (et l'explication de l'autoscaler de nœuds), le drain, le pic KEDA, les recommandations VPA et la correction des requests.", "Le Deployment de référence mis à jour avec les requests mesurées."],
 ["Pourquoi pas de limite CPU sur l'API ? Le throttling CFS ajoute de la latence même quand le nœud a du CPU libre ; la request suffit au scheduler.", "Que se passe-t-il si l'HPA et le VPA agissent sur la même métrique CPU ? Ils se battent : VPA en recommandation seulement, ou sur la mémoire."])

# ================================================================ Niveau 6
C(32, [
 ("Logs JSON structurés dans CrisisShield", "<!-- logback-spring.xml -->\n<configuration>\n  <appender name=\"json\" class=\"ch.qos.logback.core.ConsoleAppender\">\n    <encoder class=\"net.logstash.logback.encoder.LogstashEncoder\">\n      <includeMdcKeyName>trace_id</includeMdcKeyName><includeMdcKeyName>span_id</includeMdcKeyName><includeMdcKeyName>user_id</includeMdcKeyName>\n      <fieldNames><timestamp>ts</timestamp><message>msg</message><logger>logger</logger></fieldNames>\n      <customFields>{\"service\":\"api\",\"env\":\"${ENV:-dev}\"}</customFields>\n    </encoder>\n  </appender>\n  <root level=\"INFO\"><appender-ref ref=\"json\"/></root>\n</configuration>\n// filtre de masquage : un ValueMasker sur email et téléphone ; user_id en MDC après authentification, jamais l'email\nk kubectl logs -n crisis deploy/api --tail 1", "{\"ts\":\"2026-09-22T10:41:02.318Z\",\"level\":\"INFO\",\"logger\":\"fr.crisisshield.IncidentService\",\"msg\":\"incident created\",\"service\":\"api\",\"env\":\"dev\",\"trace_id\":\"4f2c…\",\"span_id\":\"9a1b\",\"user_id\":\"u-4821\",\"incident_id\":42}", ["Une ligne = un événement JSON avec les mêmes champs partout ; le <code>trace_id</code> vient du MDC alimenté par OpenTelemetry.", "Masquer à la source : un email dans un log est une donnée personnelle stockée 30 jours dans Loki."]),
 ("Alloy et Loki sur le cluster", "k helm repo add grafana https://grafana.github.io/helm-charts && k helm install loki grafana/loki -n observability --create-namespace --version 6.16.0 -f loki-values.yaml   # mode SingleBinary, stockage MinIO, rétention 7 j dev / 30 j prod\nk helm install alloy grafana/alloy -n observability -f alloy-values.yaml   # discovery.kubernetes pods → loki.process (labels : namespace, app, pod ; drop des lignes health) → loki.write\nk kubectl -n observability port-forward svc/loki-gateway 3100:80 &\ncurl -s -G localhost:3100/loki/api/v1/query_range --data-urlencode 'query={namespace=\"crisis\",app=\"api\"} | json | level=\"ERROR\"' | jq '.data.result | length'", "2 flux (deux Pods) ; les lignes ERROR de l'API sont interrogeables", ["Trois labels (namespace, app, pod) : la cardinalité reste basse ; tout le reste (level, user_id) est extrait à la requête par <code>| json</code>.", "Les lignes de healthcheck sont supprimées par Alloy : 40 % du volume en moins, zéro perte d'information."]),
 ("LogQL utile, et une alerte sur les logs", "# Grafana → Explore → Loki\nsum by (app) (count_over_time({namespace=\"crisis\"} | json | level=\"ERROR\" [5m]))\n{namespace=\"crisis\", app=\"api\"} | json | user_id=\"u-4821\" | line_format \"{{.ts}} {{.msg}} trace={{.trace_id}}\"\n# règle Loki (ruler) : sum(rate({namespace=\"crisis\", app=\"api\"} | json | level=\"ERROR\" [5m])) > 1 → alerte « erreurs API » (symptôme, ticket)", "api 12, worker 3   (par 5 minutes)\ndeux lignes pour l'utilisateur, avec trace cliquable vers Tempo", ["Un log d'erreur seul n'est pas une alerte ; un taux d'erreurs qui monte, oui : c'est la frontière logs → métriques.", "Le lien vers Tempo se configure dans la source de données Loki (derived field sur trace_id)."]),
 ("Rétention, coût, et données personnelles", "# loki-values : limits_config.retention_period 720h prod, 168h dev ; compactor activé ; MinIO avec règle de cycle de vie\n# tp32.md : volume ingéré par jour (metrics Loki : loki_distributor_bytes_received_total), coût estimé, liste des champs masqués et pourquoi (RGPD : minimisation)\ncurl -s localhost:3100/loki/api/v1/label/__name__/values 2>/dev/null ; curl -s 'localhost:9090/api/v1/query?query=sum(rate(loki_distributor_bytes_received_total[1h]))*86400/1e9' | jq -r '.data.result[0].value[1]'", "≈ 0.8 Go/jour ingérés (dev)", ["La rétention est une décision de coût et de conformité, écrite, pas une valeur par défaut.", "Un journal contenant des données personnelles est un traitement au sens du RGPD : le masquage à la source évite le sujet."]),
], ["<code>logback-spring.xml</code> JSON avec trace_id et masquage, valeurs Helm de Loki et d'Alloy versionnées, trois requêtes LogQL sauvegardées, une règle d'alerte sur les logs.", "<code>tp32.md</code> : une ligne de log annotée champ par champ, le volume ingéré et la rétention par environnement, la liste des champs masqués.", "Le cours joint : pourquoi JSON, pourquoi peu de labels, comment expliquer Loki contre Elasticsearch en entretien."],
 ["Pourquoi ne pas indexer user_id comme label ? Des millions de valeurs : Loki créerait un flux par utilisateur et s'effondrerait.", "Que fait-on des logs au niveau DEBUG en production ? On ne les émet pas ; on change le niveau à chaud (actuator/loggers) le temps d'un diagnostic."])

C(33, [
 ("Prometheus par opérateur, cibles, et les métriques de CrisisShield", "k helm repo add prometheus-community https://prometheus-community.github.io/helm-charts && k helm install kps prometheus-community/kube-prometheus-stack -n observability --version 65.1.0 -f kps-values.yaml\n# Spring : micrometer-registry-prometheus, management.endpoints.web.exposure.include=health,prometheus ; @Timed sur les contrôleurs ; un Counter incidents_created_total{zone,priority}\nk kubectl apply -f - <<'EOF'\napiVersion: monitoring.coreos.com/v1\nkind: ServiceMonitor\nmetadata: { name: api, namespace: crisis, labels: { release: kps } }\nspec: { selector: { matchLabels: { app: api } }, endpoints: [{ port: http, path: /actuator/prometheus, interval: 15s }] }\nEOF\nk kubectl -n observability port-forward svc/kps-kube-prometheus-stack-prometheus 9090:9090 &\ncurl -s 'localhost:9090/api/v1/targets' | jq '[.data.activeTargets[] | select(.labels.job==\"api\") | .health]'", "[\"up\",\"up\",\"up\"]   (les trois Pods sont scrapés)", ["Le ServiceMonitor doit porter le label que l'opérateur sélectionne (<code>release: kps</code>) : l'oubli classique quand « les cibles n'apparaissent pas ».", "Le compteur métier <code>incidents_created_total</code> est ce qui reliera les incidents techniques à leur impact."]),
 ("RED et USE en PromQL, sur de vraies données", "# débit\nsum by (uri) (rate(http_server_requests_seconds_count{job=\"api\"}[5m]))\n# erreurs\n100 * sum(rate(http_server_requests_seconds_count{job=\"api\",status=~\"5..\"}[5m])) / sum(rate(http_server_requests_seconds_count{job=\"api\"}[5m]))\n# durée p95\nhistogram_quantile(0.95, sum by (le) (rate(http_server_requests_seconds_bucket{job=\"api\"}[5m])))\n# USE nœuds\n1 - avg by (instance) (rate(node_cpu_seconds_total{mode=\"idle\"}[5m]))\ncontainer_memory_working_set_bytes{namespace=\"crisis\",container=\"api\"} / on(pod) group_left kube_pod_container_resource_limits{resource=\"memory\",container=\"api\"}", "débit 61 req/s ; erreurs 0,54 % ; p95 142 ms ; CPU nœud 38 % ; mémoire api 71 % de la limite", ["<code>histogram_quantile</code> sur les buckets agrégés par <code>le</code> : jamais de moyenne de latence, jamais de quantile calculé côté client puis moyenné.", "Le ratio erreurs / total doit avoir les mêmes labels des deux côtés : c'est la raison des <code>sum</code> symétriques."]),
 ("Tableau de bord Grafana en code", "# dashboards/api.json : 4 lignes RED (débit, erreurs, p50/p95/p99, saturation), 1 ligne métier (incidents par zone), variables $namespace $service, annotations de déploiement\nk kubectl create cm dash-api -n observability --from-file=dashboards/api.json --dry-run=client -o yaml | k kubectl label --local -f - grafana_dashboard=1 -o yaml | k kubectl apply -f -\ncurl -s -u admin:$GRAFANA_PW localhost:3000/api/search?query=api | jq '.[0].title'", "\"CrisisShield API — RED\"", ["Le tableau de bord vit dans Git et arrive par ConfigMap : reproductible, revu, versionné ; jamais édité à la main en production.", "Quatre lignes lisibles en dix secondes ; les détails dans des panneaux secondaires."]),
 ("Cardinalité, rétention, longue durée", "topk(10, count by (__name__)({__name__=~\".+\"}))\ncount({__name__=~\"http_server_requests.*\"})\n# kps-values : retention 15d, retentionSize 20GB ; remote_write vers Mimir ou VictoriaMetrics pour 13 mois ; recording rules pour les requêtes des dashboards", "http_server_requests_seconds_bucket : 4 200 séries (uri × status × method × le) ; une uri avec id → à normaliser (/incidents/{id})", ["Une URI avec un identifiant dans le chemin explose la cardinalité : Spring la normalise si les routes sont déclarées avec des variables, sinon filtrer la métrique.", "Recording rules : les requêtes lourdes des tableaux de bord sont précalculées ; Prometheus reste rapide."]),
], ["kube-prometheus-stack avec ServiceMonitor de l'API, métriques Micrometer et un compteur métier, les cinq requêtes RED/USE, un tableau de bord en JSON versionné, la rétention et le remote_write configurés.", "<code>tp33.md</code> : les cibles up, les valeurs RED mesurées pendant un test k6, la capture du tableau de bord, le top 10 de cardinalité et la correction apportée.", "Les recording rules commitées."],
 ["Pourquoi <code>rate</code> et pas <code>increase</code> pour un taux ? rate normalise par seconde et gère les remises à zéro ; increase donne un total sur la fenêtre.", "Que représente le label <code>le</code> ? La borne supérieure du bucket d'histogramme : histogram_quantile interpole entre les buckets."])

C(34, [
 ("Instrumentation automatique OpenTelemetry", "k kubectl apply -f https://github.com/cert-manager/cert-manager/releases/download/v1.15.3/cert-manager.yaml\nk kubectl apply -f https://github.com/open-telemetry/opentelemetry-operator/releases/latest/download/opentelemetry-operator.yaml\nk kubectl apply -f - <<'EOF'\napiVersion: opentelemetry.io/v1alpha1\nkind: Instrumentation\nmetadata: { name: java, namespace: crisis }\nspec:\n  exporter: { endpoint: http://otel-collector.observability:4318 }\n  propagators: [tracecontext, baggage]\n  sampler: { type: parentbased_traceidratio, argument: \"1\" }\n  java: { image: ghcr.io/open-telemetry/opentelemetry-operator/autoinstrumentation-java:2.8.0 }\nEOF\nk kubectl patch deploy api -n crisis -p '{\"spec\":{\"template\":{\"metadata\":{\"annotations\":{\"instrumentation.opentelemetry.io/inject-java\":\"true\"}}}}}'\nk kubectl logs -n crisis deploy/api | grep -m1 'otel.javaagent'", "[otel.javaagent 2.8.0] … started", ["Zéro ligne de code : l'agent Java est injecté par un init container ; il instrumente Spring MVC, JDBC, Kafka, HttpClient.", "Le sampler à 100 % en dev ; en prod, tail sampling au Collector (garder les erreurs et les lentes)."]),
 ("Collector et Tempo", "k helm install otel-collector open-telemetry/opentelemetry-collector -n observability -f otel-values.yaml   # mode deployment, receivers otlp, processors: memory_limiter, k8sattributes, batch, tail_sampling (erreurs, > 500 ms, 10 % du reste), exporters: otlp → tempo, prometheus (spanmetrics)\nk helm install tempo grafana/tempo -n observability --version 1.10.3 -f tempo-values.yaml   # stockage MinIO, rétention 72 h, metrics_generator activé\ncurl -s localhost:8888/metrics 2>/dev/null | grep -E 'otelcol_receiver_accepted_spans|otelcol_exporter_sent_spans' | tail -2", "otelcol_receiver_accepted_spans{receiver=\"otlp\"} 18 420\notelcol_exporter_sent_spans{exporter=\"otlp/tempo\"} 2 310   (tail sampling : 12 % conservés)", ["Le Collector est le point de contrôle : échantillonnage, enrichissement Kubernetes, limitation mémoire ; les applications n'exportent qu'au Collector.", "Le metrics generator de Tempo produit les métriques RED par service à partir des traces : un service graph gratuit."]),
 ("Une trace lue de bout en bout, et corrélée", "# Grafana → Explore → Tempo → TraceQL : { resource.service.name = \"api\" && duration > 500ms }\n# la trace montre api → geo-service → PostgreSQL : le span SELECT zones dure 610 ms\n# depuis le span : « Logs for this span » (Loki, par trace_id) ; depuis le tableau de bord RED : exemplar → trace\ncurl -s 'localhost:3200/api/search?q=%7Bduration%3E500ms%7D' | jq '.traces | length'", "7 traces lentes sur la dernière heure, toutes avec le span geo-service SELECT zones", ["Métrique (p95 monte) → exemplar → trace (quel span) → logs (quel message) : c'est la corrélation par trace_id que le chapitre demande.", "La cause est la même que le TP 45 : un index manquant, trouvé en trois clics."]),
 ("Propagation à travers Kafka, et coût", "// producteur : l'agent propage traceparent dans les en-têtes Kafka ; consommateur (worker) : span enfant lié ; vérifier dans Tempo que la trace traverse la file\n// coût : spans par seconde × taille ; tail sampling à 10 % + 100 % des erreurs ; rétention 72 h ; tp34.md : volume avant/après", "trace incident → Kafka → notification : un seul trace_id, 3 services", ["Sans propagation à travers la file, la trace s'arrête au producteur : la moitié du système devient invisible.", "Le coût des traces se règle par l'échantillonnage, jamais en supprimant l'instrumentation."]),
], ["Opérateur OpenTelemetry avec Instrumentation Java, Collector avec tail sampling et k8sattributes, Tempo avec metrics generator, sources Grafana reliées (Loki ↔ Tempo ↔ Prometheus).", "<code>tp34.md</code> : une trace annotée span par span, la capture de la corrélation métrique → trace → log, la trace à travers Kafka, les compteurs du Collector avant/après échantillonnage.", "Aucune modification du code de CrisisShield (instrumentation automatique) ; une phrase sur ce que l'instrumentation manuelle ajouterait (spans métier)."],
 ["Pourquoi le tail sampling au Collector et pas le head sampling dans l'agent ? On ne sait qu'à la fin qu'une trace est lente ou en erreur.", "Que contient le contexte propagé (traceparent) ? trace_id, span_id parent, flags ; 55 octets dans un en-tête."])

C(35, [
 ("SLI, SLO, et les recording rules", "# SLI disponibilité : requêtes non 5xx / total ; SLI latence : requêtes < 300 ms / total ; SLO : 99,9 % et 95 % sur 30 j\nk kubectl apply -f - <<'EOF'\napiVersion: monitoring.coreos.com/v1\nkind: PrometheusRule\nmetadata: { name: api-slo, namespace: crisis, labels: { release: kps } }\nspec:\n  groups:\n    - name: api-sli\n      rules:\n        - record: sli:api_availability:ratio_rate5m\n          expr: 1 - (sum(rate(http_server_requests_seconds_count{job=\"api\",status=~\"5..\"}[5m])) / sum(rate(http_server_requests_seconds_count{job=\"api\"}[5m])))\n        - record: sli:api_availability:ratio_rate1h\n          expr: 1 - (sum(rate(http_server_requests_seconds_count{job=\"api\",status=~\"5..\"}[1h])) / sum(rate(http_server_requests_seconds_count{job=\"api\"}[1h])))\n        - record: sli:api_availability:ratio_rate6h\n          expr: 1 - (sum(rate(http_server_requests_seconds_count{job=\"api\",status=~\"5..\"}[6h])) / sum(rate(http_server_requests_seconds_count{job=\"api\"}[6h])))\nEOF\ncurl -s 'localhost:9090/api/v1/query?query=sli:api_availability:ratio_rate1h' | jq -r '.data.result[0].value[1]'", "0.9946   (99,46 % sur la dernière heure : sous le SLO)", ["Le SLI est un ratio bon / total ; la recording rule le précalcule sur plusieurs fenêtres pour le burn rate.", "Sloth ou Pyrra génèrent tout ça depuis un fichier de 10 lignes : à utiliser dès que tu as plus de deux SLO."]),
 ("Alertes de burn rate multi-fenêtres", "        - alert: ApiErrorBudgetBurnFast\n          expr: (1 - sli:api_availability:ratio_rate1h) > (14.4 * 0.001) and (1 - sli:api_availability:ratio_rate5m) > (14.4 * 0.001)\n          for: 2m\n          labels: { severity: page, service: api }\n          annotations: { summary: \"API : budget d'erreur brûlé 14× (1h/5m)\", runbook_url: https://gitlab.local/crisisshield/runbooks/-/blob/main/api-errors.md }\n        - alert: ApiErrorBudgetBurnSlow\n          expr: (1 - sli:api_availability:ratio_rate6h) > (6 * 0.001) and (1 - sli:api_availability:ratio_rate30m) > (6 * 0.001)\n          for: 15m\n          labels: { severity: ticket, service: api }\n# test : docker run … promtool test rules tests/api-slo.test.yaml", "promtool : SUCCESS (2 tests) ; en injectant 2 % d'erreurs pendant 3 min avec k6, l'alerte page part à T+2 min", ["Fenêtre longue pour la gravité, courte pour « en cours » : l'alerte se tait dès que ça s'arrête, et ne réveille pas pour un pic de 30 s.", "Un <code>runbook_url</code> sur chaque alerte de page, sinon l'alerte n'est pas acceptée en revue."]),
 ("Alertmanager : routage, regroupement, silences, astreinte", "# alertmanager-config : route par severity → receiver page (Grafana OnCall ou webhook), ticket (Slack + GitLab issue) ; group_by [service, alertname] ; repeat_interval 4h ; inhibit : page inhibe ticket du même service\ncurl -s -XPOST localhost:9093/api/v2/silences -d '{\"matchers\":[{\"name\":\"service\",\"value\":\"api\",\"isRegex\":false}],\"startsAt\":\"2026-09-22T22:00:00Z\",\"endsAt\":\"2026-09-22T23:00:00Z\",\"createdBy\":\"gael\",\"comment\":\"migration planifiée\"}'\ncurl -s localhost:9093/api/v2/alerts | jq '[.[] | .labels.alertname]'", "silence créé pour la fenêtre de maintenance ; alertes actives : [\"ApiErrorBudgetBurnSlow\"]", ["Le regroupement évite dix notifications pour un incident ; l'inhibition évite le ticket pendant la page.", "Un silence a un auteur, un commentaire et une fin : jamais de silence permanent."]),
 ("Revue des alertes et politique de budget d'erreur", "# tp35.md : tableau de toutes les alertes (nom, symptôme ou cause ?, action, runbook, nombre de déclenchements sur 30 j) ; suppression de celles sans action\n# docs/error-budget-policy.md : SLO par service, ce qui se passe à 50 % consommé (revue), 100 % (gel des changements non fiabilité), qui signe", "12 alertes → 7 après revue (5 sans action supprimées) ; politique signée « produit » et « ingénierie »", ["Une alerte sans action documentée est du bruit : elle sort de la liste ou devient un ticket.", "La politique de budget d'erreur est le contrat que le Tech Lead SRE fera appliquer au chapitre 43."]),
], ["Les PrometheusRules de SLI (trois fenêtres), deux alertes de burn rate avec runbook, les tests promtool, la configuration Alertmanager avec routage, regroupement et inhibition, un silence exemple.", "<code>tp35.md</code> : la valeur du SLI mesurée, la chronologie du test d'alerte (injection d'erreurs → page à T+2 min → silence à l'arrêt), le tableau de revue des alertes avant/après, la politique de budget d'erreur.", "Sloth ou Pyrra en option, avec le fichier de 10 lignes qui génère l'équivalent."],
 ["Pourquoi 14,4 ? Avec ce burn rate, le budget de 30 jours disparaît en 2 jours : le seuil qui justifie de réveiller quelqu'un.", "Que fait-on quand le SLO est tenu à 99,99 % alors qu'il est à 99,9 % ? On dépense le budget : plus de risque, plus de changements, ou on baisse l'objectif."])

C(36, [
 ("Préparer le game day : rôles, scénarios, hypothèses", "# docs/gameday/2026-09-plan.md : date, participants (commandant, opérations, communication, scribe : ta seule personne joue les rôles à tour de rôle, ou avec un collègue), trois scénarios (base primaire perdue, Pod api en OOM en boucle, réseau vers Kafka coupé), pour chacun : hypothèse d'état stable (SLO tenu, bascule < 30 s), rayon d'impact (namespace crisis), critères d'arrêt", "plan validé, fenêtre annoncée, tableaux de bord et runbooks ouverts", ["Un game day se prépare comme un déploiement : hypothèse écrite avant, critères d'arrêt, communication.", "Le rayon d'impact est borné : jamais toute la plateforme la première fois."]),
 ("Chaos Mesh : les trois expériences, mesurées", "k helm repo add chaos-mesh https://charts.chaos-mesh.org && k helm install chaos-mesh chaos-mesh/chaos-mesh -n chaos-mesh --create-namespace --version 2.7.0 --set chaosDaemon.runtime=containerd --set chaosDaemon.socketPath=/run/containerd/containerd.sock\nk kubectl apply -f - <<'EOF'\napiVersion: chaos-mesh.org/v1alpha1\nkind: PodChaos\nmetadata: { name: kill-db-primary, namespace: crisis }\nspec: { action: pod-kill, mode: one, selector: { namespaces: [crisis], labelSelectors: { cnpg.io/instanceRole: primary } } }\n---\napiVersion: chaos-mesh.org/v1alpha1\nkind: NetworkChaos\nmetadata: { name: kafka-partition, namespace: crisis }\nspec: { action: partition, mode: all, selector: { namespaces: [crisis], labelSelectors: { app: api } }, direction: to, target: { mode: all, selector: { namespaces: [crisis], labelSelectors: { app: kafka } } }, duration: \"2m\" }\nEOF\n# pendant chaque expérience : k6 en fond, tableau de bord SLO ouvert, chronomètre", "scénario 1 : bascule en 4 s, 3 requêtes en erreur, SLO tenu → hypothèse confirmée\nscénario 2 : OOM répété : CrashLoop 2 min, readiness retire le Pod, 0 erreur utilisateur → confirmée\nscénario 3 : Kafka coupé : l'API renvoie 202 et met en file locale (outbox), notifications en retard de 2 min, 0 perte → confirmée, mais aucune alerte n'a signalé le retard", ["Chaque expérience produit un résultat contre l'hypothèse ; le troisième révèle un trou d'observabilité : c'est exactement ce que le game day doit trouver.", "Le ChaosDaemon a besoin du bon socket de runtime (containerd sur kind)."]),
 ("Un incident joué en vrai, avec les rôles", "# déclarer : « SEV2 — notifications en retard » ; commandant nomme les rôles ; canal ; chronologie tenue par le scribe (horodatages) ; communication toutes les 15 min (statut, impact, prochaine mise à jour) ; mitigation (rétablir le réseau) ; résolution ; clôture\n# chronologie dans docs/incidents/2026-09-22-notifications.md", "T+0 déclaration, T+3 rôles, T+8 cause identifiée (partition), T+11 mitigé, T+20 résolu, 2 communications", ["Même simulé, l'incident se joue avec les vrais rôles et la vraie communication : c'est la répétition qui rend l'astreinte calme.", "La chronologie horodatée est la matière première du post-mortem."]),
 ("Post-mortem sans blâme, actions suivies", "# docs/postmortems/2026-09-22-notifications.md : résumé, impact (chiffré), chronologie, causes (5 pourquoi : pas d'alerte sur le lag Kafka → pas de SLO sur la latence des notifications → pas d'owner du sujet), ce qui a bien marché, actions (SLO notification < 60 s, alerte KEDA lag, test mensuel), propriétaire et échéance par action, tickets créés\n# revue de fiabilité hebdomadaire : les actions ouvertes de plus de 30 jours remontent", "3 actions créées avec propriétaire et date ; 1 SLO ajouté ; le game day est reprogrammé dans un mois", ["Le post-mortem cherche ce qui a rendu l'incident possible, pas qui l'a provoqué (ici, personne : c'est le chaos).", "Une action sans propriétaire ni date n'existe pas ; elles sont suivies dans le backlog, pas dans un document."]),
], ["Le plan de game day, les trois manifests Chaos Mesh, les résultats mesurés contre les hypothèses, la chronologie de l'incident joué, le post-mortem avec actions datées.", "<code>tp36.md</code> : le tableau hypothèse / résultat / écart pour chaque scénario, la chronologie, les trois actions et leur ticket.", "Le calendrier des game days (trimestriel) commité."],
 ["Pourquoi commencer le chaos en staging et avec un rayon borné ? Pour apprendre à mesurer avant de risquer la production ; le vrai gain vient en production, plus tard.", "Que fait-on d'un game day où tout se passe bien ? On augmente le rayon ou la sévérité : un game day sans surprise n'a rien appris."])

if __name__ == '__main__':
    print('pages :', write_all(range(20, 37)))
